import { z } from "zod";

/**
 * User preferences, stored as one `profiles.preferences` jsonb bag.
 *
 * Defaults live here rather than in the database so a row written before a
 * preference existed reads correctly instead of behaving as `undefined`.
 *
 * `rainGuard` defaults ON because the protective behaviour already shipped
 * inside `weatherRules` — defaulting it off would silently change the generator
 * for every existing user. `tempUnit` defaults to Celsius because every stored
 * threshold, and the text sent to the model, is Celsius; the unit is a display
 * choice and never reaches the rules.
 *
 * Only preferences something actually reads belong here. A stored flag that no
 * code consults is a switch that lies to the user.
 */
export const PreferencesSchema = z.object({
  rainGuard: z.boolean().default(true).catch(true),
  tempUnit: z.enum(["C", "F"]).default("C").catch("C"),
});

export type Preferences = z.infer<typeof PreferencesSchema>;

/**
 * Read the stored bag, repairing anything unreadable.
 *
 * `.catch()` sits on each field rather than the object, so one malformed value
 * falls back on its own instead of discarding every other preference alongside
 * it. The write path (`PreferencesSchema.partial()`) does NOT forgive — garbage
 * is rejected before it is stored, not silently repaired on every later read.
 */
export function readPreferences(raw: unknown): Preferences {
  const source = raw && typeof raw === "object" ? raw : {};
  return PreferencesSchema.parse(source);
}

