input.command:
cat >> lib/outfits/local-date.ts <<'EOF'

/**
 * The user's local hour, 0–23.
 *
 * Same reasoning as `localDateFor`, and the same fallback: the evening
 * confirmation asks after 18:00 LOCAL, so a UTC hour would put the question in
 * the afternoon for eastern users and after midnight for western ones.
 *
 * `hourCycle: "h23"` because the default for some locales is `h24`, which
 * renders midnight as "24" and would parse to an hour that never compares less
 * than the evening threshold.
 */
export function localHourFor(now: Date, timeZone: string): number {
  try {
    const hh = new Intl.DateTimeFormat("en-GB", {
      timeZone,
      hour: "2-digit",
      hourCycle: "h23",
    }).format(now);
    return Number(hh);
  } catch {
    return now.getUTCHours();
  }
}
EOF
cat >> lib/outfits/__tests__/local-date.test.ts <<'EOF'

test("localHourFor reads the hour in the user's zone, not UTC", () => {
  const t = new Date("2026-08-13T20:00:00Z");
  expect(localHourFor(t, "UTC")).toBe(20);
  expect(localHourFor(t, "Asia/Tokyo")).toBe(5); // next morning
  expect(localHourFor(t, "America/Los_Angeles")).toBe(13); // still afternoon
});

test("midnight is 0, never 24", () => {
  // Some locales default to h24 and render midnight as "24", which would never
  // compare below the evening threshold — the confirmation would ask at 00:00.
  expect(localHourFor(new Date("2026-08-13T00:00:00Z"), "UTC")).toBe(0);
});

test("an unknown zone falls back rather than throwing", () => {
  expect(localHourFor(new Date("2026-08-13T20:00:00Z"), "Not/AZone")).toBe(20);
});
EOF
